begin;
create function pg_temp.check_true(value boolean,label text) returns void language plpgsql as $$
begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end; $$;
insert into auth.users(id,email,created_at,updated_at,aud,role,is_anonymous) values('84000000-0000-4000-8000-000000000001','bot-fixture@example.test',now(),now(),'authenticated','authenticated',false);
insert into auth.sessions(id,user_id,created_at,updated_at) values('84000000-0000-4000-8000-000000000011','84000000-0000-4000-8000-000000000001',now(),now());
do $$ declare account jsonb; person uuid; project uuid; receipt jsonb; note uuid; replay jsonb; ctx jsonb; payload jsonb; count_before integer;
begin
  select count(*) into count_before from public.account_profiles;
  receipt:=public.account_prepare_telegram(840001,jsonb_build_object('user_id',840001,'chat_id',840001,'display_name','Metadata only','sent_at',extract(epoch from now())::bigint,'kind','note','text','Do not persist this unlinked message'),'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(receipt->>'status'='saved' and receipt->>'submission_id' is null,'Unlinked messages create no site record');
  perform pg_temp.check_true((select count(*) from public.account_profiles)=count_before,'Bot start never creates a standalone person');
  perform pg_temp.check_true(not (receipt->'payload' ? 'text'),'Unlinked chat input is not saved');
  account:=public.account_browser_session('84000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000011',repeat('a',64),'Professional Name');person:=(account->>'profile_id')::uuid;
  perform public.account_verified_email(repeat('a',64),'84000000-0000-4000-8000-000000000001','84000000-0000-4000-8000-000000000011');
  perform public.account_link_miniapp(repeat('a',64),840001,repeat('b',64),true);
  project:=(public.account_create_project(repeat('a',64),'Bot fixture','Fixture client','Fixture site','0','NGN','Africa/Lagos')->>'id')::uuid;
  ctx:=public.account_bot_context(840001);
  perform pg_temp.check_true(ctx->>'professional_name'='Professional Name' and (ctx->>'project_id')::uuid=project,'Bot uses shared professional identity and selected project');
  payload:=jsonb_build_object('user_id',840001,'chat_id',840001,'display_name','Never the recorded name','sent_at',extract(epoch from now())::bigint,'kind','voice','file_id','fixture-voice','content_type','audio/ogg');
  receipt:=public.account_prepare_telegram(840002,payload,'84000000-0000-4000-8000-000000000021');note:=(receipt->>'submission_id')::uuid;
  perform pg_temp.check_true(receipt->>'status'='pending' and note is not null,'Authorized voice reserves one private submission');
  perform pg_temp.check_true((select submitted_by='Professional Name' from public.submissions where id=note),'Telegram display metadata is never professional attribution');
  perform pg_temp.check_true((select role='pm' and profile_id=person from public.account_submission_people where submission_id=note),'Solo PM intake is honestly snapshotted');
  replay:=public.account_prepare_telegram(840002,payload,'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(replay->>'submission_id'=note::text,'Repeated delivery does not duplicate notes');
  perform public.account_archive_project(repeat('a',64),project,true);
  perform pg_temp.check_true(public.account_resume_telegram(840001,'84000000-0000-4000-8000-000000000021') is null,'Archived media cannot resume through a fresh bot command');
  replay:=public.account_prepare_telegram(840002,payload,'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(replay->>'status'='blocked' and replay->>'storage_path' is null,'Interrupted Telegram upload rechecks access before any download');
  perform pg_temp.check_true((select u.payload->>'file_id'='fixture-voice' from public.telegram_updates u where update_id=840002),'Blocked interrupted receipt preserves its original media reference');
  perform public.account_archive_project(repeat('a',64),project,false);
  perform pg_temp.check_true(public.account_resume_telegram(840001,'84000000-0000-4000-8000-000000000021')->>'submission_id'=note::text,'Restored original project can resume the reserved media without duplication');
  begin perform public.account_prepare_telegram(840002,jsonb_set(payload,'{file_id}','"different-file"'),'84000000-0000-4000-8000-000000000021');raise exception 'Changed replay unexpectedly passed';exception when raise_exception then if sqlerrm<>'Telegram replay payload changed' then raise;end if;end;
  perform public.account_finish_telegram_media(840002,'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true((select audio_url='site-evidence/'||(receipt->>'storage_path') from public.submissions where id=note),'Original media belongs to captured project');
  receipt:=public.account_prepare_telegram(840003,jsonb_build_object('user_id',840001,'chat_id',840001,'display_name','Metadata','sent_at',extract(epoch from now())::bigint,'kind','reports'),'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(receipt->>'reply_path'='/projects/'||project::text,'Reports command opens authorized history');
  perform public.account_archive_project(repeat('a',64),project,true);
  receipt:=public.account_prepare_telegram(840004,payload,'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(receipt->>'submission_id' is null and receipt->>'reply_text' like '%archived%','Archived project rejects new voice intake');
  perform pg_temp.check_true(not (receipt->'payload' ? 'file_id'),'Rejected media is not downloaded or saved');
  receipt:=public.account_prepare_telegram(840005,jsonb_build_object('user_id',840001,'chat_id',840001,'display_name','Metadata','sent_at',extract(epoch from now())::bigint,'kind','logout'),'84000000-0000-4000-8000-000000000021');
  perform pg_temp.check_true(public.account_bot_context(840001) is null,'Bot logout revokes Telegram access');
  perform pg_temp.check_true((select count(*)=1 from public.submissions where id=note),'Logout preserves original evidence');
end $$;
rollback;
